mkdir -p tests/tmp-merge && cat > tests/tmp-merge/merge.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as labelService from "@/server/services/label-service";
import { mergeLabelsSchema } from "@/schemas/label";
import { NotFoundError } from "@/server/services/_support";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("merge", () => {
  it("works", async () => {
    const t = await createTenant("m1");
    const o = await createTenant("m2");
    const bug = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#000000", description: null });
    const defect = await labelRepo.insertLabel({ orgId: t.org.id, name: "defect", color: "#000000", description: null });
    const other = await labelRepo.insertLabel({ orgId: t.org.id, name: "other", color: "#000000", description: null });
    const foreign = await labelRepo.insertLabel({ orgId: o.org.id, name: "x", color: "#000000", description: null });
    const i1 = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id) as never, t.userIds.owner, 1);
    const i2 = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id) as never, t.userIds.owner, 2);
    const i3 = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id) as never, t.userIds.owner, 3);
    await labelRepo.setIssueLabels(t.org.id, i1.id, [defect.id]);
    await labelRepo.setIssueLabels(t.org.id, i2.id, [defect.id, bug.id, other.id]);
    await labelRepo.setIssueLabels(t.org.id, i3.id, [other.id]);

    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: bug.id, targetLabelId: bug.id }).success).toBe(false);
    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id }).success).toBe(true);

    await expect(labelService.mergeLabels(t.actors.member, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(labelService.mergeLabels(t.actors.owner, { orgId: o.org.id, sourceLabelId: defect.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(labelService.mergeLabels(t.actors.owner, { orgId: t.org.id, sourceLabelId: foreign.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(labelService.mergeLabels(t.actors.owner, { orgId: t.org.id, sourceLabelId: bug.id, targetLabelId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(labelService.mergeLabels(t.actors.owner, { orgId: t.org.id, sourceLabelId: bug.id, targetLabelId: bug.id })).rejects.toThrow();

    const res = await labelService.mergeLabels(t.actors.admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id });
    expect(res.issuesRelabelled).toBe(2);
    expect(res.label.id).toBe(bug.id);
    const map = await labelRepo.listLabelsForIssues(t.org.id, [i1.id, i2.id, i3.id]);
    expect(map[i1.id]!.map((l) => l.name)).toEqual(["bug"]);
    expect(map[i2.id]!.map((l) => l.name).sort()).toEqual(["bug", "other"]);
    expect(map[i3.id]!.map((l) => l.name)).toEqual(["other"]);
    expect((await labelRepo.listLabels(t.org.id)).map((l) => l.name)).toEqual(["bug", "other"]);
    expect((await labelRepo.listLabels(o.org.id)).length).toBe(1);
  });
});
EOF
npx vitest run tests/tmp-merge 2>&1 | tail -20

